import json, re, sys, glob, os

# /tmp (または /private/tmp) に書く書き方: リダイレクト・tee・mkdir・cp/mv の宛先・go build -o など
W = re.compile(r"(>>?\s*|tee\s+(-a\s+)?|mkdir\s+(-p\s+)?|-o\s+)(/private)?/tmp/")
ANY = re.compile(r"(?<![\w.$}/-])(/private)?/tmp/")

for path in sorted(glob.glob(sys.argv[1])):
    uses = {}
    order = []
    results = {}
    last_text = {}
    for line in open(path, encoding="utf-8", errors="replace"):
        try:
            o = json.loads(line)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        t = o.get("type")
        parent = o.get("parent_tool_use_id")
        msg = o.get("message") if isinstance(o.get("message"), dict) else {}
        for c in msg.get("content") or []:
            if not isinstance(c, dict):
                continue
            if t == "assistant" and c.get("type") in ("text", "thinking"):
                last_text[parent] = (c.get("text") or c.get("thinking") or "")[-300:]
            if t == "assistant" and c.get("type") == "tool_use" and c.get("name") == "Bash":
                cmd = (c.get("input") or {}).get("command", "")
                if ANY.search(cmd):
                    uses[c["id"]] = (parent, cmd, last_text.get(parent, ""))
                    order.append(c["id"])
            if t == "user" and c.get("type") == "tool_result" and c.get("tool_use_id") in uses:
                body = c.get("content")
                if isinstance(body, list):
                    body = "\n".join(x.get("text", "") for x in body if isinstance(x, dict))
                results[c["tool_use_id"]] = body or ""
    if not order:
        continue
    print("=" * 10, os.path.relpath(path, os.path.dirname(os.path.dirname(path))))
    for i in order:
        parent, cmd, before = uses[i]
        body = results.get(i, "")
        blocked = "operation not permitted" in body.lower() or "<sandbox_violations>" in body
        writes = bool(W.search(cmd))
        print(f"- sub-agent={bool(parent)} writes={writes} blocked={blocked}")
        print("  cmd:", cmd[:400].replace("\n", "⏎"))
        if blocked:
            print("  before:", before.replace("\n", " ")[-300:])
            print("  body:", body[:300].replace("\n", "⏎"))

import json, re, sys

# 引数: ログのパス。/tmp に書いた Bash の呼び出しを含む sub-agent について、Agent の入力 (種類とプロンプト) を出す
path = sys.argv[1]
agents = {}
bad_parents = set()
first_user = {}
for line in open(path, encoding="utf-8", errors="replace"):
    try:
        o = json.loads(line)
    except ValueError:
        continue
    if not isinstance(o, dict):
        continue
    t = o.get("type")
    parent = o.get("parent_tool_use_id")
    msg = o.get("message") if isinstance(o.get("message"), dict) else {}
    content = msg.get("content")
    if t == "user" and parent and parent not in first_user:
        first_user[parent] = content
    for c in content if isinstance(content, list) else []:
        if not isinstance(c, dict):
            continue
        if t == "assistant" and c.get("type") == "tool_use" and c.get("name") in ("Agent", "Task"):
            agents[c["id"]] = c.get("input")
        if t == "assistant" and c.get("type") == "tool_use" and c.get("name") == "Bash" and parent:
            cmd = (c.get("input") or {}).get("command", "")
            if re.search(r">\s*/tmp/", cmd):
                bad_parents.add(parent)
for p in bad_parents:
    inp = agents.get(p) or {}
    print("=== agent", p, "type:", inp.get("subagent_type"), "desc:", inp.get("description"))
    prompt = inp.get("prompt", "")
    print("prompt length:", len(prompt))
    for kw in ["/tmp", "TMPDIR", "tmp/", "一時", "複製", "使い捨て", "作業ツリー"]:
        print(f"  contains {kw!r}:", kw in prompt)
    print("--- prompt head")
    print(prompt[:1500])
    fu = first_user.get(p)
    s = json.dumps(fu, ensure_ascii=False) if fu is not None else ""
    print("--- first user message of sub-agent: len", len(s), "claudeMd:", "CLAUDE.md" in s, "system-reminder:", "system-reminder" in s)

