"""probe.sh が残したログとフックの記録を読み、Issue #80 の候補 (A) と (B) の前提の答えを出す。
引数: ログのパス、フックの記録のパス。
"""

import json, sys

log, calls = sys.argv[1], sys.argv[2]
uses, results, result, subagents = {}, {}, None, {}
for line in open(log, encoding="utf-8", errors="replace"):
    try:
        o = json.loads(line)
    except ValueError:
        continue
    if not isinstance(o, dict):
        continue
    t = o.get("type")
    if t == "system" and o.get("subtype") == "task_started":
        subagents[o.get("tool_use_id")] = f"{o.get('description')} ({o.get('subagent_type')})"
    if t == "result":
        result = o
    msg = o.get("message") if isinstance(o.get("message"), dict) else {}
    for c in msg.get("content") or []:
        if not isinstance(c, dict):
            continue
        if t == "assistant" and c.get("type") == "tool_use":
            uses[c["id"]] = (o.get("parent_tool_use_id"), c.get("name"), c.get("input"))
        if t == "user" and c.get("type") == "tool_result":
            b = c.get("content")
            if isinstance(b, list):
                b = "\n".join(x.get("text", "") for x in b if isinstance(x, dict))
            results[c.get("tool_use_id")] = (bool(c.get("is_error")), (b or "")[:300])

print("## 1. ツールの呼び出し (どこから呼ばれたか・APPEND80 の接頭辞が付いたか・結果)")
for i, (parent, name, inp) in uses.items():
    where = "最上位" if not parent else "sub-agent: " + subagents.get(parent, parent)
    if name == "Bash":
        cmd = (inp or {}).get("command", "")
        err, body = results.get(i, (None, ""))
        print(f"- [{where}] Bash 接頭辞={cmd.lstrip().startswith(': APPEND80;')} is_error={err}")
        print("    command:", cmd[:160].replace("\n", "⏎"))
        print("    result :", body[:200].replace("\n", "⏎"))
    else:
        print(f"- [{where}] {name}: {json.dumps(inp, ensure_ascii=False)[:160]}")

print()
print("## 2. result の行")
if result is None:
    print("result の行が無い (実行が最後まで終わらなかった)")
else:
    print("permission_denials:", json.dumps(result.get("permission_denials"), ensure_ascii=False, indent=1))
    print("total_cost_usd:", result.get("total_cost_usd"), "/ num_turns:", result.get("num_turns"))
    print("最終の応答:")
    print(result.get("result"))

print()
print("## 3. フックが受け取った呼び出し")
try:
    for line in open(calls, encoding="utf-8"):
        print("-", line.rstrip())
except OSError as e:
    print("フックの記録を読めない:", e)

